self.__next_f.push([1,"31:[\"$\",\"section\",null,{\"id\":\"$undefined\",\"data-theme\":\"light\",\"data-page-builder-section\":\"animatedListSection\",\"className\":\"bg-background pt-64 lg:pt-128 pb-64 lg:pb-128\",\"children\":[\"$\",\"$L3d\",null,{\"headline\":{\"level\":\"h2\",\"text\":\"How we work.\"},\"label\":\"// Process\",\"text\":null,\"items\":[{\"_key\":\"1ddd8f27d17f\",\"alt\":\"Pick a plan. Pay monthly. Cancel anytime.\",\"headline\":\"Send us a brief.\",\"image\":{\"_id\":\"image-728234c6dbc099bb9ffd7ab8160a443b7ed9b239-1600x2400-heif\",\"_rev\":\"LKoX4P0z7W6obIGRbVvqYd\",\"altText\":\"Julian and Adrian dressed in black in a minimalist studio, one seated on a chair and one standing behind, both facing the camera\",\"crop\":null,\"description\":\"A minimalist studio portrait of two creatives featuring contrasting seated and standing poses, styled in dark clothing and captured against a clean, neutral backdrop.\",\"dimensions\":{\"_type\":\"sanity.imageDimensions\",\"aspectRatio\":0.6666666666666666,\"height\":2400,\"width\":1600},\"hotspot\":null,\"lqip\":\"data:image/jpeg;base64,\",\"title\":\"Minimal studio portrait of Julian and Adrian with seated and standing poses\"},\"text\":\"One paragraph is enough. We reply within two business days with whether the shape is right for what we do.\"},{\"_key\":\"23106ef3aef5\",\"alt\":\"Submit work via Slack. Or email. Or wherever you work. We tackle one request at a time, in your priority order.\",\"headline\":\"One conversation.\",\"image\":{\"_id\":\"image-8c7de2558b412dbf660620894a264bfc0a21dd46-1600x2400-heif\",\"_rev\":\"LKoX4P0z7W6obIGRbVtVXv\",\"altText\":\"Adrian and Julian dressed in black sitting on the floor and looking at a laptop together in a minimalist studio\",\"crop\":null,\"description\":\"A minimalist studio portrait of Adrian and Julian seated on the floor reviewing work on a laptop, captured with a clean, modern aesthetic and a collaborative mood.\",\"dimensions\":{\"_type\":\"sanity.imageDimensions\",\"aspectRatio\":0.6666666666666666,\"height\":2400,\"width\":1600},\"hotspot\":null,\"lqip\":\"data:image/jpeg;base64,\",\"title\":\"Minimal collaborative portrait of Adrian and Julian reviewing work\"},\"text\":\"You tell us where the brand is going. We give you a clear picture of the artifact, the timeline and the cost before you commit to anything.\"},{\"_key\":\"69d8077d7c34\",\"alt\":\"Ship\",\"headline\":\"Design and build.\",\"image\":{\"_id\":\"image-dacef92f30d8e3ebe3c32ed098eb878f39e133ef-1600x2400-heif\",\"_rev\":\"LKoX4P0z7W6obIGRbVt6xz\",\"altText\":\"Blurred motion image of Julian and Adrian dressed in black walking past each other in a minimalist studio\",\"crop\":null,\"description\":\"An abstract studio portrait capturing motion blur as Julian and Adrian walking past each other, blending movement, minimalism, and a contemporary visual aesthetic.\",\"dimensions\":{\"_type\":\"sanity.imageDimensions\",\"aspectRatio\":0.6666666666666666,\"height\":2400,\"width\":1600},\"hotspot\":null,\"lqip\":\"data:image/jpeg;base64,\",\"title\":\"Abstract motion portrait of Julian and Adrian walking in studio\"},\"text\":\"Both brothers on every project, custom-coded from the ground up. Engagements run six to twelve weeks. Motion is the medium, running through every transition, scroll moment and interaction.\"},{\"_key\":\"a0a61e5ab386\",\"alt\":\"Laptop and Magazine on the ground\",\"headline\":\"Ship.\",\"image\":{\"_id\":\"image-b370e4f512a2d26bb53dd93bc1d84b473ffcb988-2400x1600-heif\",\"_rev\":\"YTJXK0pSg0Faj6IAyiENH2\",\"altText\":\"Top-down view of black shoes and patterned socks on a white floor beside an open magazine, a closed laptop, and a glass of water\",\"crop\":null,\"description\":\"A minimalist flat lay capturing a creative workspace on a white floor, featuring an open magazine, a laptop, and subtle lifestyle details with a clean, modern aesthetic.\",\"dimensions\":{\"_type\":\"sanity.imageDimensions\",\"aspectRatio\":1.5,\"height\":1600,\"width\":2400},\"hotspot\":null,\"lqip\":\"data:image/jpeg;base64,\",\"title\":\"Minimal flat lay of creative workspace with magazine and laptop\"},\"text\":\"The site lands as the brand's landmark online.\"}],\"variant\":\"standard\",\"headlineDisplay\":\"$undefined\",\"fixedMedia\":null}]}]\n"])

