self.__next_f.push([1,"34:[\"$\",\"section\",null,{\"id\":\"$undefined\",\"data-page-builder-section\":\"accordionSection\",\"data-theme\":\"dark\",\"data-selector\":\"$undefined\",\"className\":\"bg-background py-64 lg:py-96\",\"children\":[\"$\",\"div\",null,{\"className\":\"grid-container\",\"children\":[\"$\",\"div\",null,{\"className\":\"grid-layout\",\"children\":[[\"$\",\"div\",null,{\"className\":\"grid-span-12 lg:grid-span-4 sticky top-0 z-10 -mx-(--site-grid-margin) bg-background px-(--site-grid-margin) pt-header pb-32 lg:top-header lg:z-auto lg:mx-0 lg:bg-transparent lg:px-0 lg:pt-32\",\"children\":[[\"$\",\"$L3f\",null,{\"trigger\":\"scroll\",\"as\":\"h2\",\"displayAs\":\"$undefined\",\"className\":\"\",\"wrapperClassName\":\"$undefined\",\"children\":\"Common questions\"}],null]}],[\"$\",\"div\",null,{\"className\":\"grid-span-12 lg:grid-span-6 lg:grid-start-6 mt-48 lg:mt-0\",\"children\":[\"$\",\"$L40\",null,{\"items\":[{\"_key\":\"f7659804d967\",\"headline\":\"How do you work with our existing brand book and design system?\",\"text\":[{\"_key\":\"ffa2b7fcc6c6\",\"_type\":\"block\",\"children\":[{\"_key\":\"da9017e812c5\",\"_type\":\"span\",\"marks\":[],\"text\":\"We start by living inside the brand book and the design system. Whatever your typography and motion principles have already defined, we carry through end to end. The job is to make the site finally match what the brand has been saying.\"}],\"markDefs\":[],\"style\":\"normal\"}]},{\"_key\":\"53317e715920\",\"headline\":\"Who do I actually work with on the project?\",\"text\":[{\"_key\":\"b5a62a3e7344\",\"_type\":\"block\",\"children\":[{\"_key\":\"ae1c48026bc8\",\"_type\":\"span\",\"marks\":[],\"text\":\"Both brothers on every project. You stay with the same people from kickoff through launch. The people you talk to are the people writing the code.\"}],\"markDefs\":[],\"style\":\"normal\"}]},{\"_key\":\"b96143354a69\",\"headline\":\"How long does a project take?\",\"text\":[{\"_key\":\"67e8dce56525\",\"_type\":\"block\",\"children\":[{\"_key\":\"af5fbdb033c9\",\"_type\":\"span\",\"marks\":[],\"text\":\"Most engagements run six to twelve weeks from first conversation to launch. We give you a clear timeline before you commit and we work on fewer parallel projects than most studios so the timeline holds.\"}],\"markDefs\":[],\"style\":\"normal\"}]},{\"_key\":\"c97b9c60ac0c\",\"headline\":\"Do you work with brands that need commerce on the site?\",\"text\":[{\"_key\":\"535ecf9f18e9\",\"_type\":\"block\",\"children\":[{\"_key\":\"c817320b4bd1\",\"_type\":\"span\",\"marks\":[],\"text\":\"Yes, as long as the brand is the point of the site and commerce sits inside it. Think Nothing, Loewe, On Running. If your site is built primarily to convert, that's a different craft and there are studios who specialize in it.\"}],\"markDefs\":[],\"style\":\"normal\"}]},{\"_key\":\"568e5a3f1301\",\"headline\":\"What technology do you build with?\",\"text\":[{\"_key\":\"74ca7975e17e\",\"_type\":\"block\",\"children\":[{\"_key\":\"e4ef8c26d682\",\"_type\":\"span\",\"marks\":[],\"text\":\"Custom-coded from the ground up. The stack fits the brand, not the other way around. We don't build with Framer or Webflow and the site never sits on a page-builder substrate.\"}],\"markDefs\":[],\"style\":\"normal\"}]},{\"_key\":\"40cf1828d007\",\"headline\":\"What happens after the site ships?\",\"text\":[{\"_key\":\"7006c636dcde\",\"_type\":\"block\",\"children\":[{\"_key\":\"5ab3dac66acd\",\"_type\":\"span\",\"marks\":[],\"text\":\"We hand over a site you fully own. The code and the design system are yours. Engagements close cleanly. If you want us to keep building, that's a separate conversation and we work on follow-ups only when there's something specific to ship next.\"}],\"markDefs\":[],\"style\":\"normal\"}]}]}]}]]}]}]}]\n"])

